#include <WiFi.h>
#include <WebServer.h>

const char* SSID = "YOUR_WIFI";
const char* PASS = "YOUR_PASS";
const int LED = 2;            // on-board LED on many ESP32 devkits
WebServer server(80);
bool ledOn = false;

String page() {
  return "<!doctype html><meta name=viewport content='width=device-width,initial-scale=1'>"
         "<h1>ESP32</h1><p>LED is " + String(ledOn ? "ON" : "OFF") + "</p>"
         "<p><a href='/toggle'><button style='padding:12px 20px;font-size:18px'>Toggle</button></a></p>";
}
void handleRoot()   { server.send(200, "text/html", page()); }
void handleToggle() { ledOn = !ledOn; digitalWrite(LED, ledOn); server.sendHeader("Location", "/"); server.send(303); }

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  WiFi.begin(SSID, PASS);
  Serial.print("Connecting");
  while (WiFi.status() != WL_CONNECTED) { delay(300); Serial.print('.'); }
  Serial.println(); Serial.print("Open http://"); Serial.println(WiFi.localIP());
  server.on("/", handleRoot);
  server.on("/toggle", handleToggle);
  server.begin();
}
void loop() { server.handleClient(); }
